@JvmName("step40")
fun step40(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 57
}
fun <T> List<T>.secondOrNull41(): T? = if (size > 1) this[1] else null

fun render41(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
sealed class Outcome42 {
    data class Success(val payload: String) : Outcome42()
    data object Failure : Outcome42()
}

fun describe42(outcome: Outcome42): String = when (outcome) {
    is Outcome42.Success -> outcome.payload
    Outcome42.Failure -> "failed"
}
